import React, { useRef, useEffect } from 'react';

export default function MeshSphere({ size = 320, speed = 0.4, distort = 0.5, color = '#f2f0eb', opacity = 1 }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    const draw = () => {
      t.current += 0.004 * speed;
      ctx.clearRect(0, 0, size, size);

      const cx = size / 2, cy = size / 2, r = size * 0.42;
      const lats = 18, lons = 26;

      // Parse color to rgba
      const alpha = (a) => {
        if (color.startsWith('#')) {
          const hex = color.slice(1);
          const rgb = parseInt(hex, 16);
          const rr = (rgb >> 16) & 255, gg = (rgb >> 8) & 255, bb = rgb & 255;
          return `rgba(${rr},${gg},${bb},${a})`;
        }
        return color;
      };

      // Project 3D point with distortion
      const project = (lat, lon, extraDistort = 0) => {
        const phi   = (lat / lats) * Math.PI;
        const theta = (lon / lons) * Math.PI * 2 + t.current;

        // Distortion — organic warp
        const d = distort + extraDistort;
        const warp = 1
          + Math.sin(phi * 3 + t.current * 0.6)  * 0.08 * d
          + Math.cos(theta * 2 + t.current * 0.8) * 0.05 * d
          + Math.sin(phi * 5 + theta + t.current) * 0.03 * d;

        const sr = r * warp;
        const x = cx + sr * Math.sin(phi) * Math.cos(theta);
        const y = cy + sr * Math.cos(phi);
        const z = sr * Math.sin(phi) * Math.sin(theta); // depth
        return { x, y, z };
      };

      // Draw latitude lines
      for (let lat = 0; lat <= lats; lat++) {
        const pts = [];
        for (let lon = 0; lon <= lons; lon++) {
          pts.push(project(lat, lon));
        }
        // Depth-based opacity
        for (let i = 0; i < pts.length - 1; i++) {
          const avgZ = (pts[i].z + pts[i+1].z) / 2;
          const depthAlpha = ((avgZ / r) + 1) / 2; // 0-1
          const lineAlpha = (0.08 + depthAlpha * 0.35) * opacity;
          ctx.beginPath();
          ctx.moveTo(pts[i].x, pts[i].y);
          ctx.lineTo(pts[i+1].x, pts[i+1].y);
          ctx.strokeStyle = alpha(lineAlpha);
          ctx.lineWidth = 0.6 + depthAlpha * 0.4;
          ctx.stroke();
        }
      }

      // Draw longitude lines
      for (let lon = 0; lon < lons; lon++) {
        const pts = [];
        for (let lat = 0; lat <= lats; lat++) {
          pts.push(project(lat, lon));
        }
        for (let i = 0; i < pts.length - 1; i++) {
          const avgZ = (pts[i].z + pts[i+1].z) / 2;
          const depthAlpha = ((avgZ / r) + 1) / 2;
          const lineAlpha = (0.08 + depthAlpha * 0.3) * opacity;
          ctx.beginPath();
          ctx.moveTo(pts[i].x, pts[i].y);
          ctx.lineTo(pts[i+1].x, pts[i+1].y);
          ctx.strokeStyle = alpha(lineAlpha);
          ctx.lineWidth = 0.5 + depthAlpha * 0.4;
          ctx.stroke();
        }
      }

      // Subtle inner glow
      const glow = ctx.createRadialGradient(cx - r*0.2, cy - r*0.2, 0, cx, cy, r);
      glow.addColorStop(0, alpha(0.06 * opacity));
      glow.addColorStop(1, 'transparent');
      ctx.beginPath();
      ctx.arc(cx, cy, r * 1.05, 0, Math.PI * 2);
      ctx.fillStyle = glow;
      ctx.fill();

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, speed, distort, color, opacity]);

  return (
    <canvas ref={canvasRef}
      style={{ display:'block', width:`${size}px`, height:`${size}px`, maxWidth:'100%' }}
    />
  );
}
